@Composable fun RoboApp(ctx:Context){MaterialTheme(colorScheme=darkColorScheme(background=Background,surface=Background,primary=BrightBlue)){var logged by remember{mutableStateOf(ApiClient.loggedIn())};if(logged) MainTabs(ctx){ApiClient.logout(ctx);logged=false}else Login{logged=true}}}
@Composable fun Bg(content:@Composable ColumnScope.()->Unit){Box(Modifier.fillMaxSize().background(Background)){Image(androidx.compose.ui.res.painterResource(com.robo.reseller.R.drawable.robo_logo),null,Modifier.fillMaxWidth().padding(top=170.dp).alpha(.055f),contentScale=ContentScale.Fit);Column(Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(horizontal=16.dp,vertical=8.dp),content=content)}}
@Composable fun Header(compact:Boolean=true){Column(horizontalAlignment=Alignment.CenterHorizontally,modifier=Modifier.fillMaxWidth()){Image(androidx.compose.ui.res.painterResource(com.robo.reseller.R.drawable.robo_logo),null,Modifier.width(if(compact)150.dp else 245.dp).height(if(compact)60.dp),contentScale=ContentScale.Fit);if(!compact)Text("RESELLER PORTAL",fontSize=11.sp,fontWeight=FontWeight.SemiBold,color=BrightBlue,letterSpacing=3.sp)}}
@Composable fun CardBox(content:@Composable ColumnScope.()->Unit){Column(content=content,modifier=Modifier.fillMaxWidth().clip(RoundedCornerShape(18.dp)).background(Card).border(1.dp,Blue,RoundedCornerShape(18.dp)).padding(16.dp),verticalArrangement=Arrangement.spacedBy(12.dp))}
@Composable fun Login(onLogin:()->Unit){var u by remember{mutableStateOf("")};var p by remember{mutableStateOf("")};var err by remember{mutableStateOf("")};var loading by remember{mutableStateOf(false)};val scope=rememberCoroutineScope();Bg{Spacer(Modifier.height(25.dp));Header(false);CardBox{Text("WELCOME BACK",fontSize=13.sp,fontWeight=FontWeight.Bold,color=BrightBlue,letterSpacing=2.sp);OutlinedTextField(u,{u=it},label={Text("Username")},singleLine=true,modifier=Modifier.fillMaxWidth(),colors=fieldColors());OutlinedTextField(p,{p=it},label={Text("Password")},singleLine=true,modifier=Modifier.fillMaxWidth(),visualTransformation=androidx.compose.ui.text.input.PasswordVisualTransformation(),colors=fieldColors());if(err.isNotEmpty())Text(err,color=Color.White,fontSize=13.sp);Button(onClick={scope.launch{loading=true;err="";try{val x=ApiClient.login(androidx.compose.ui.platform.LocalContext.current,u,p);if(x.role.lowercase()!="reseller"){ApiClient.logout(androidx.compose.ui.platform.LocalContext.current);throw Exception("Please sign in with a reseller account.")};onLogin()}catch(e:Exception){err=e.message?:"Login failed"};loading=false}},enabled=u.isNotBlank()&&p.isNotBlank()&&!loading,modifier=Modifier.fillMaxWidth(),colors=ButtonDefaults.buttonColors(containerColor=Blue),shape=RoundedCornerShape(14.dp)){if(loading)CircularProgressIndicator(modifier=Modifier.size(18.dp),color=Color.White);Spacer(Modifier.width(10.dp));Text("SIGN IN",fontWeight=FontWeight.Bold,letterSpacing=1.2.sp)}};Spacer(Modifier.height(25.dp));Text("SECURE ACCESS • ROBO ANDROID",fontSize=10.sp,color=MutedWhite,letterSpacing=1.5.sp)}}
private fun fieldColors()=OutlinedTextFieldDefaults.colors(focusedBorderColor=BrightBlue,unfocusedBorderColor=Blue,focusedTextColor=Color.White,unfocusedTextColor=Color.White,focusedLabelColor=BrightBlue,unfocusedLabelColor=MutedWhite)
@Composable fun MainTabs(ctx:Context,onLogout:()->Unit){var tab by remember{mutableIntStateOf(0)};val titles=listOf("ROBO ANDROID","PRODUCTS","MY KEYS","UPDATES");Scaffold(containerColor=Background,topBar={CenterAlignedTopAppBar(title={Text(titles[tab],fontWeight=FontWeight.Bold)},colors=TopAppBarDefaults.centerAlignedTopAppBarColors(containerColor=Background,titleContentColor=Color.White))},bottomBar={NavigationBar(containerColor=Color.Black){listOf(Icons.Default.Home,Icons.Default.GridView,Icons.Default.Key,Icons.Default.Download).forEachIndexed{i,ic->NavigationBarItem(selected=tab==i,onClick={tab=i},icon={Icon(ic,null)},label={Text(listOf("Home","Products","My Keys","Updates")[i])},colors=NavigationBarItemDefaults.colors(selectedIconColor=BrightBlue,selectedTextColor=BrightBlue,unselectedIconColor=MutedWhite,unselectedTextColor=MutedWhite,indicatorColor=Card))}}}){pad->Box(Modifier.padding(pad)){when(tab){0->Home(ctx,onLogout);1->Products(ctx);2->Keys();3->Updates(ctx)}}}}
@Composable fun Home(ctx:Context,onLogout:()->Unit){var user by remember{mutableStateOf<ApiUser?>(null)};var err by remember{mutableStateOf("")};LaunchedEffect(Unit){try{user=ApiClient.me()}catch(e:Exception){err=e.message?:"Request failed"}};Bg{Header();if(user!=null)CardBox{Text("ACCOUNT OVERVIEW",fontSize=12.sp,fontWeight=FontWeight.Bold,color=BrightBlue,letterSpacing=1.6.sp);Row(Modifier.fillMaxWidth()){Text("Username",color=MutedWhite);Spacer(Modifier.weight(1f));Text(user!!.username)};Row(Modifier.fillMaxWidth()){Text("Role",color=MutedWhite);Spacer(Modifier.weight(1f));Text(user!!.role.replaceFirstChar{it.uppercase()})};HorizontalDivider(color=Blue);Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically){Column{Text("AVAILABLE BALANCE",fontSize=12.sp,fontWeight=FontWeight.Bold,color=MutedWhite);Text(String.format(Locale.US,"$%.2f",user!!.balance),fontSize=32.sp,fontWeight=FontWeight.Bold)};Spacer(Modifier.weight(1f));Icon(Icons.Default.AccountBalanceWallet,null,tint=BrightBlue,modifier=Modifier.size(32.dp))}}else if(err.isNotEmpty())CardBox{Text(err)}else CircularProgressIndicator(color=BrightBlue);Spacer(Modifier.height(18.dp));CardBox{Text("QUICK ACCESS",fontSize=12.sp,fontWeight=FontWeight.Bold,color=BrightBlue,letterSpacing=1.6.sp);Text("Manage your products, keys and latest updates from one place.");Row{Icon(Icons.Default.GridView,null,tint=BrightBlue);Text("Products",color=BrightBlue);Spacer(Modifier.weight(1f));Icon(Icons.Default.Key,null,tint=BrightBlue);Text("Keys",color=BrightBlue)}};Spacer(Modifier.height(12.dp));OutlinedButton(onClick=onLogout,modifier=Modifier.fillMaxWidth(),border=BorderStroke(1.dp,Blue)){Icon(Icons.Default.Logout,null);Spacer(Modifier.width(8.dp));Text("Log Out")}}}
@Composable fun Products(ctx:Context){var products by remember{mutableStateOf<List<Product>>(emptyList())};var err by remember{mutableStateOf("")};var busy by remember{mutableStateOf(false)};var dialog by remember{mutableStateOf<String?>(null)};val scope=rememberCoroutineScope();suspend fun load(){busy=true;try{products=ApiClient.products();err=""}catch(e:Exception){err=e.message?:"Request failed"};busy=false};LaunchedEffect(Unit){load()};Bg{Header();if(err.isNotEmpty())CardBox{Text(err)};if(products.isEmpty()&&err.isEmpty()&&!busy)CardBox{Icon(Icons.Default.GridView,null,tint=BrightBlue,modifier=Modifier.size(38.dp));Text("NO PRODUCTS",fontWeight=FontWeight.Bold);Text("Products will appear here when available.",color=MutedWhite)};products.forEach{p->CardBox{Text(p.name,fontSize=20.sp,fontWeight=FontWeight.Bold);p.description?.takeIf{it.isNotBlank()}?.let{Text(it,fontSize=14.sp,color=MutedWhite)};p.version?.takeIf{it.isNotBlank()}?.let{Text("VERSION  $it",fontSize=12.sp,fontWeight=FontWeight.Bold,color=BrightBlue)};p.categories.forEach{c->Column(Modifier.fillMaxWidth().clip(RoundedCornerShape(14.dp)).background(Color.Black).border(1.dp,Blue,RoundedCornerShape(14.dp)).padding(12.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){Row(Modifier.fillMaxWidth()){Column{Text(c.name,fontWeight=FontWeight.Bold);Text("${c.available_count} available",fontSize=12.sp,color=MutedWhite)};Spacer(Modifier.weight(1f));Text(String.format(Locale.US,"$%.2f",c.price_cents/100.0),fontWeight=FontWeight.Bold,color=BrightBlue)};Button(onClick={scope.launch{busy=true;try{val r=ApiClient.getKey(c.id);dialog="KEY\n${r.key}\nNew balance: ${String.format(Locale.US,"$%.2f",r.balance)}";products=ApiClient.products()}catch(e:Exception){dialog=e.message?:"Purchase failed"};busy=false}},enabled=c.available_count>0&&!busy,modifier=Modifier.fillMaxWidth(),colors=ButtonDefaults.buttonColors(containerColor=Blue),shape=RoundedCornerShape(12.dp)){Icon(Icons.Default.Key,null);Spacer(Modifier.width(8.dp));Text("GET KEY",fontWeight=FontWeight.Bold,letterSpacing=1.sp)}}};p.download_url?.takeIf{it.isNotBlank()}?.let{url->TextButton(onClick={ctx.startActivity(Intent(Intent.ACTION_VIEW,Uri.parse(url)))}){Icon(Icons.Default.Download,null);Spacer(Modifier.width(5.dp));Text("Product Download",color=BrightBlue)}}}};if(busy)CircularProgressIndicator(color=BrightBlue);if(dialog!=null)AlertDialog(onDismissRequest={dialog=null},confirmButton={TextButton({dialog=null}){Text("OK")}},text={Text(dialog!!)},containerColor=Card)}}
@Composable fun Keys(){var keys by remember{mutableStateOf<List<KeyRecord>>(emptyList())};var err by remember{mutableStateOf("")};LaunchedEffect(Unit){try{keys=ApiClient.keys()}catch(e:Exception){err=e.message?:"Request failed"}};Bg{Header();if(err.isNotEmpty())CardBox{Text(err)};if(keys.isEmpty()&&err.isEmpty())CardBox{Icon(Icons.Default.Key,null,tint=BrightBlue,modifier=Modifier.size(38.dp));Text("NO KEYS YET",fontWeight=FontWeight.Bold);Text("Purchased keys will appear here.",color=MutedWhite)};keys.forEach{k->CardBox{Row(verticalAlignment=Alignment.CenterVertically){Icon(Icons.Default.Key,null,tint=BrightBlue);Text(k.category_name.uppercase(),fontSize=12.sp,fontWeight=FontWeight.Bold,color=BrightBlue);Spacer(Modifier.weight(1f));Text(k.status.uppercase(),fontSize=11.sp,fontWeight=FontWeight.Bold)};Text(k.key_value,fontFamily=FontFamily.Monospace,fontWeight=FontWeight.SemiBold);Text(k.product_name,fontSize=14.sp,color=MutedWhite);k.issued_at?.takeIf{it.isNotBlank()}?.let{Text("Issued: $it",fontSize=11.sp,color=MutedWhite)}}}}}
@Composable fun Updates(ctx:Context){var updates by remember{mutableStateOf<List<PanelUpdate>>(emptyList())};var err by remember{mutableStateOf("")};LaunchedEffect(Unit){try{updates=ApiClient.updates()}catch(e:Exception){err=e.message?:"Request failed"}};Bg{Header();if(err.isNotEmpty())CardBox{Text(err)};if(updates.isEmpty()&&err.isEmpty())CardBox{Icon(Icons.Default.Download,null,tint=BrightBlue,modifier=Modifier.size(38.dp));Text("NO UPDATES",fontWeight=FontWeight.Bold);Text("Published updates will appear here.",color=MutedWhite)};updates.forEach{u->CardBox{Row{Text(u.product_name,fontWeight=FontWeight.Bold);Spacer(Modifier.weight(1f));if(u.is_latest==true)Text("LATEST",fontSize=11.sp,fontWeight=FontWeight.Bold,color=BrightBlue,modifier=Modifier.border(1.dp,BrightBlue,RoundedCornerShape(20.dp)).padding(horizontal=9.dp,vertical=5.dp))};Text("${u.version} — ${u.title}",fontWeight=FontWeight.Bold,color=BrightBlue);u.patch_notes?.takeIf{it.isNotBlank()}?.let{Text(it)};u.release_date?.takeIf{it.isNotBlank()}?.let{Text(it,fontSize=11.sp,color=MutedWhite)};u.download_url?.takeIf{it.isNotBlank()}?.let{url->Button(onClick={ctx.startActivity(Intent(Intent.ACTION_VIEW,Uri.parse(url)))},modifier=Modifier.fillMaxWidth(),colors=ButtonDefaults.buttonColors(containerColor=Blue),shape=RoundedCornerShape(12.dp)){Icon(Icons.Default.Download,null);Spacer(Modifier.width(6.dp));Text("DOWNLOAD UPDATE",fontWeight=FontWeight.Bold)}}}}}}
